import { Controller, Get, Post, Put, HttpCode, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

const ROLE = '예산·회계 담당자';
const DEFAULT_SIZE = 20;
const MAX_SIZE = 200;
// 마감·승인 상태는 마감취소·승인취소 없이 수정할 수 없다
const LOCKED_STATUSES = ['마감', '승인'];

function invalid(message: string): ApiError {
  return new ApiError(422, 'MAIN_BUDGET_INVALID', message);
}

function intOf(value: unknown): number | null {
  if (typeof value === 'number' && Number.isInteger(value)) {
    return value;
  }
  if (typeof value === 'string' && /^\d{1,15}$/.test(value.trim())) {
    return Number(value.trim());
  }
  return null;
}

function amountOf(value: unknown): string | null {
  if (typeof value !== 'number' && typeof value !== 'string') {
    return null;
  }
  const text = String(value).trim();
  return /^\d{1,16}(\.\d{1,2})?$/.test(text) ? text : null;
}

function dateOf(value: unknown): string | null {
  if (typeof value !== 'string') {
    return null;
  }
  const text = value.trim();
  return /^\d{4}-(0[1-9]|1[0-2])-(0[1-9]|[12]\d|3[01])$/.test(text) ? text : null;
}

function optionalInt(value: unknown, label: string): number | null {
  if (value === undefined || value === null || value === '') {
    return null;
  }
  const n = intOf(value);
  if (n === null) {
    throw new ApiError(400, 'VALIDATION_FAILED', label + ' 형식이 올바르지 않습니다.');
  }
  return n;
}

function optionalText(value: unknown): string | null {
  if (typeof value !== 'string' || value.trim() === '') {
    return null;
  }
  return value.trim();
}

@Controller('api/v1')
export class FnSfr00301Controller {
  @Get('/main-budgets/targets')
  async listMainBudgetTargets(@Req() req: Request) {
    const user = currentUser(req);
    user.require(ROLE);
    const query = checks.queryOf(req.query);
    const accountingUnit = optionalText(query['accountingUnit']);
    const fiscalYear = optionalInt(query['fiscalYear'], '기수');
    const projectId = optionalInt(query['projectId'], '프로젝트 ID');
    const budgetGroup = optionalText(query['budgetGroup']);
    const page = optionalInt(query['page'], '쪽') ?? 0;
    let size = optionalInt(query['size'], '건수') ?? DEFAULT_SIZE;
    if (size < 1) {
      size = DEFAULT_SIZE;
    }
    if (size > MAX_SIZE) {
      size = MAX_SIZE;
    }
    return transaction(async (db) => {
      const from =
        ' FROM budget_item bi CROSS JOIN project p' +
        " WHERE p.use_status = '사용'" +
        ' AND (CAST(:budgetGroup AS varchar) IS NULL OR bi.budget_group = CAST(:budgetGroup AS varchar))' +
        ' AND (CAST(:projectId AS bigint) IS NULL OR p.project_id = CAST(:projectId AS bigint))' +
        ' AND (CAST(:accountingUnit AS varchar) IS NULL OR CAST(:fiscalYear AS integer) IS NULL OR NOT EXISTS (' +
        ' SELECT 1 FROM main_budget mb' +
        ' WHERE mb.budget_item_id = bi.budget_item_id AND mb.project_id = p.project_id' +
        ' AND mb.accounting_unit = CAST(:accountingUnit AS varchar)' +
        ' AND mb.fiscal_year = CAST(:fiscalYear AS integer)' +
        " AND mb.status IN ('마감', '승인')))";
      const filter = { accountingUnit, fiscalYear, projectId, budgetGroup };
      const items = await db.query(
        'SELECT bi.budget_item_id AS "budgetItemId", bi.item_code AS "itemCode", bi.item_name AS "itemName",' +
          ' bi.budget_group AS "budgetGroup", p.project_id AS "projectId", p.project_name AS "projectName"' +
          from +
          ' ORDER BY bi.item_code, p.project_code LIMIT :size OFFSET :offset',
        { ...filter, size, offset: page * size },
      );
      const counted = await db.query('SELECT COUNT(*) AS total' + from, filter);
      const total = Number(counted[0]?.total ?? 0);
      return { items, page, size, total };
    });
  }

  @Post('/main-budgets')
  @HttpCode(200)
  async createMainBudget(@Req() req: Request) {
    const user = currentUser(req);
    user.require(ROLE);
    const data = checks.inputOf(req.body);
    const projectId = intOf(data['projectId']);
    const budgetItemId = intOf(data['budgetItemId']);
    const accountingUnit = optionalText(data['accountingUnit']);
    const fiscalYear = intOf(data['fiscalYear']);
    const requestAmount = amountOf(data['requestAmount']);
    const requestDate = dateOf(data['requestDate']);
    if (projectId === null) {
      throw invalid('프로젝트를 선택해 주세요.');
    }
    if (budgetItemId === null) {
      throw invalid('예산과목을 선택해 주세요.');
    }
    if (accountingUnit === null || accountingUnit.length > 50) {
      throw invalid('회계단위를 50자 이내로 입력해 주세요.');
    }
    if (fiscalYear === null) {
      throw invalid('기수(회계연도)를 숫자로 입력해 주세요.');
    }
    if (requestAmount === null) {
      throw invalid('신청금액을 0 이상의 숫자(소수 둘째 자리까지)로 입력해 주세요.');
    }
    if (requestDate === null) {
      throw invalid('신청일을 YYYY-MM-DD 형식으로 입력해 주세요.');
    }
    return transaction(async (db) => {
      const projects = await db.query('SELECT project_id FROM project WHERE project_id = CAST(:projectId AS bigint)', { projectId });
      if (projects.length === 0) {
        throw new ApiError(404, 'NOT_FOUND', '프로젝트를 찾을 수 없습니다.');
      }
      const items = await db.query('SELECT budget_item_id FROM budget_item WHERE budget_item_id = CAST(:budgetItemId AS bigint)', { budgetItemId });
      if (items.length === 0) {
        throw new ApiError(404, 'NOT_FOUND', '예산과목을 찾을 수 없습니다.');
      }
      const existing = await db.query(
        'SELECT status FROM main_budget WHERE accounting_unit = :accountingUnit AND fiscal_year = CAST(:fiscalYear AS integer)' +
          ' AND project_id = CAST(:projectId AS bigint) AND budget_item_id = CAST(:budgetItemId AS bigint)',
        { accountingUnit, fiscalYear, projectId, budgetItemId },
      );
      if (existing.length > 0) {
        if (LOCKED_STATUSES.includes(String(existing[0].status))) {
          throw new ApiError(409, 'MAIN_BUDGET_CLOSED', '이미 마감된 본예산 과목입니다. 마감취소 후 수정해 주세요.');
        }
        throw new ApiError(409, 'INVALID_STATE', '같은 회계단위·기수·프로젝트·예산과목의 본예산이 이미 신청되어 있습니다.');
      }
      const rows = await db.query(
        'INSERT INTO main_budget (project_id, budget_item_id, requester_id, accounting_unit, fiscal_year, request_amount, request_date, status, created_at, updated_at)' +
          ' VALUES (CAST(:projectId AS bigint), CAST(:budgetItemId AS bigint), CAST(:userId AS bigint), :accountingUnit, CAST(:fiscalYear AS integer),' +
          " CAST(:requestAmount AS numeric), CAST(:requestDate AS date), '신청', now(), now())" +
          ' RETURNING main_budget_id AS "mainBudgetId", status',
        { projectId, budgetItemId, userId: user.id, accountingUnit, fiscalYear, requestAmount, requestDate },
      );
      return rows[0];
    });
  }

  @Put('/main-budgets/:mainBudgetId')
  async updateMainBudget(@Req() req: Request) {
    const user = currentUser(req);
    user.require(ROLE);
    const data = checks.inputOf(req.body);
    const mainBudgetId = intOf(req.params['mainBudgetId']);
    if (mainBudgetId === null) {
      throw new ApiError(404, 'MAIN_BUDGET_NOT_FOUND', '대상 본예산을 찾을 수 없습니다.');
    }
    const requestAmount = amountOf(data['requestAmount']);
    const requestDate = dateOf(data['requestDate']);
    if (requestAmount === null) {
      throw invalid('신청금액을 0 이상의 숫자(소수 둘째 자리까지)로 입력해 주세요.');
    }
    if (requestDate === null) {
      throw invalid('신청일을 YYYY-MM-DD 형식으로 입력해 주세요.');
    }
    return transaction(async (db) => {
      const found = await db.query(
        'SELECT status FROM main_budget WHERE main_budget_id = CAST(:mainBudgetId AS bigint) FOR UPDATE',
        { mainBudgetId },
      );
      if (found.length === 0) {
        throw new ApiError(404, 'MAIN_BUDGET_NOT_FOUND', '대상 본예산을 찾을 수 없습니다.');
      }
      if (LOCKED_STATUSES.includes(String(found[0].status))) {
        throw new ApiError(409, 'MAIN_BUDGET_CLOSED', '마감 또는 승인된 본예산은 수정할 수 없습니다. 마감취소·승인취소 후 수정해 주세요.');
      }
      const rows = await db.query(
        'UPDATE main_budget SET request_amount = CAST(:requestAmount AS numeric), request_date = CAST(:requestDate AS date), updated_at = now()' +
          ' WHERE main_budget_id = CAST(:mainBudgetId AS bigint)' +
          ' RETURNING main_budget_id AS "mainBudgetId", status',
        { mainBudgetId, requestAmount, requestDate },
      );
      return rows[0];
    });
  }
}

