import { useState } from 'react';
import { call, useData, Badge, Num, DateText, Filters, Band, DataTable, Pager, Drawer, Pairs, Tiles, Form, Field, TextInput, NumberInput, DateInput, LookupSelect } from '../kit';
import type { PageProps, Row, Page } from '../kit';

const EDITABLE_STATUSES = ['신청', '마감취소', '승인취소'];
const PAGE_SIZE = 10;

function blank(value: unknown): boolean {
  return value === undefined || value === null || String(value).trim() === '';
}

export default function FnSfr00301Page({ role, notify }: PageProps) {
  const [draft, setDraft] = useState<Row>({});
  const [query, setQuery] = useState<Row>({});
  const [page, setPage] = useState(0);
  const [applying, setApplying] = useState<Row | null>(null);
  const [editing, setEditing] = useState<Row | null>(null);
  const [form, setForm] = useState<Row>({});
  const [results, setResults] = useState<Row[]>([]);

  const { data, error, reload } = useData<Page>(
    () => call<Page>('GET', '/main-budgets/targets', role, undefined, { ...query, page, size: PAGE_SIZE }),
    [query, page, role],
  );

  const setField = (key: string, value: unknown) => setForm({ ...form, [key]: value });

  const search = () => {
    setPage(0);
    setQuery({ ...draft });
  };

  const reset = () => {
    setDraft({});
    setPage(0);
    setQuery({});
  };

  const openApply = (row: Row) => {
    setForm({
      accountingUnit: query.accountingUnit ?? '',
      fiscalYear: query.fiscalYear ?? '',
      requestAmount: '',
      requestDate: '',
    });
    setApplying(row);
  };

  const openEdit = (row: Row) => {
    setForm({ requestAmount: row.requestAmount, requestDate: row.requestDate });
    setEditing(row);
  };

  const submitApply = async () => {
    if (!applying) {
      return;
    }
    if (blank(form.accountingUnit)) {
      throw new Error('회계단위를 입력해 주세요.');
    }
    if (blank(form.fiscalYear)) {
      throw new Error('기수(회계연도)를 입력해 주세요.');
    }
    if (blank(form.requestAmount)) {
      throw new Error('신청금액을 입력해 주세요.');
    }
    if (blank(form.requestDate)) {
      throw new Error('신청일을 입력해 주세요.');
    }
    const body: Row = {
      projectId: applying.projectId,
      budgetItemId: applying.budgetItemId,
      accountingUnit: form.accountingUnit,
      fiscalYear: form.fiscalYear,
      requestAmount: form.requestAmount,
      requestDate: form.requestDate,
    };
    const saved = await call('POST', '/main-budgets', role, body);
    setResults([
      {
        mainBudgetId: saved.mainBudgetId,
        status: saved.status,
        itemName: applying.itemName,
        projectName: applying.projectName,
        accountingUnit: form.accountingUnit,
        fiscalYear: form.fiscalYear,
        requestAmount: form.requestAmount,
        requestDate: form.requestDate,
      },
      ...results,
    ]);
    setApplying(null);
    notify('본예산을 신청했습니다.');
    reload();
  };

  const submitEdit = async () => {
    if (!editing) {
      return;
    }
    if (blank(form.requestAmount)) {
      throw new Error('신청금액을 입력해 주세요.');
    }
    if (blank(form.requestDate)) {
      throw new Error('신청일을 입력해 주세요.');
    }
    const saved = await call('PUT', '/main-budgets/' + String(editing.mainBudgetId), role, {
      requestAmount: form.requestAmount,
      requestDate: form.requestDate,
    });
    setResults(
      results.map((r) =>
        r.mainBudgetId === editing.mainBudgetId
          ? { ...r, status: saved.status, requestAmount: form.requestAmount, requestDate: form.requestDate }
          : r,
      ),
    );
    setEditing(null);
    notify('본예산 신청정보를 수정했습니다.');
    reload();
  };

  return (
    <div className="bento">
      <section className="box span-12">
        <h2>현황</h2>
        <Tiles
          items={[
            ['편성 대상', data ? <Num value={data.total} /> : '-'],
            ['이번 신청', <Num value={results.length} />],
          ]}
        />
      </section>

      <section className="box span-8">
        <h2>편성 대상</h2>
        <Filters onSearch={search} onReset={reset}>
          <Field label="회계단위">
            <TextInput value={draft.accountingUnit} onChange={(v) => setDraft({ ...draft, accountingUnit: v })} />
          </Field>
          <Field label="기수(회계연도)">
            <NumberInput value={draft.fiscalYear} onChange={(v) => setDraft({ ...draft, fiscalYear: v })} />
          </Field>
          <Field label="프로젝트">
            <LookupSelect table="project" role={role} value={draft.projectId} onChange={(v) => setDraft({ ...draft, projectId: v })} />
          </Field>
          <Field label="예산그룹">
            <TextInput value={draft.budgetGroup} onChange={(v) => setDraft({ ...draft, budgetGroup: v })} />
          </Field>
        </Filters>
        {error ? <p>{error}</p> : null}
        <Band total={data?.total} />
        <DataTable
          rows={data?.items ?? []}
          empty="편성 대상 예산이 없습니다."
          columns={[
            { key: 'itemCode', label: '예산과목 코드' },
            { key: 'itemName', label: '예산과목 명칭' },
            { key: 'budgetGroup', label: '예산그룹' },
            { key: 'projectName', label: '프로젝트 명칭' },
            {
              key: 'action',
              label: '처리',
              render: (row: Row) => (
                <button type="button" onClick={() => openApply(row)}>
                  신청
                </button>
              ),
            },
          ]}
        />
        <Pager page={data?.page ?? 0} size={data?.size ?? PAGE_SIZE} total={data?.total ?? 0} onPage={setPage} />
      </section>

      <section className="box span-4">
        <h2>이번 신청</h2>
        <DataTable
          rows={results}
          empty="이 화면에서 신청한 내역이 없습니다."
          columns={[
            { key: 'itemName', label: '예산과목' },
            { key: 'requestAmount', label: '신청금액', render: (r: Row) => <Num value={r.requestAmount} /> },
            { key: 'requestDate', label: '신청일', render: (r: Row) => <DateText value={r.requestDate} /> },
            { key: 'status', label: '상태', render: (r: Row) => <Badge value={r.status} /> },
            {
              key: 'action',
              label: '처리',
              render: (r: Row) =>
                EDITABLE_STATUSES.includes(String(r.status)) ? (
                  <button type="button" onClick={() => openEdit(r)}>
                    수정
                  </button>
                ) : null,
            },
          ]}
        />
      </section>

      {applying ? (
        <Drawer title="본예산 신청" onClose={() => setApplying(null)}>
          <Pairs
            items={[
              ['예산과목 명칭', String(applying.itemName ?? '')],
              ['예산그룹', String(applying.budgetGroup ?? '')],
              ['프로젝트 명칭', String(applying.projectName ?? '')],
            ]}
          />
          <Form onSubmit={submitApply} submit="신청" note="신청자는 현재 로그인한 사용자로 저장됩니다.">
            <Field label="회계단위" required>
              <TextInput value={form.accountingUnit} onChange={(v) => setField('accountingUnit', v)} />
            </Field>
            <Field label="기수(회계연도)" required>
              <NumberInput value={form.fiscalYear} onChange={(v) => setField('fiscalYear', v)} />
            </Field>
            <Field label="신청금액" required>
              <NumberInput value={form.requestAmount} onChange={(v) => setField('requestAmount', v)} />
            </Field>
            <Field label="신청일" required>
              <DateInput value={form.requestDate} onChange={(v) => setField('requestDate', v)} />
            </Field>
          </Form>
        </Drawer>
      ) : null}

      {editing ? (
        <Drawer title="본예산 수정" onClose={() => setEditing(null)}>
          <Pairs
            items={[
              ['예산과목 명칭', String(editing.itemName ?? '')],
              ['프로젝트 명칭', String(editing.projectName ?? '')],
              ['상태', <Badge value={editing.status} />],
            ]}
          />
          <Form onSubmit={submitEdit} submit="수정">
            <Field label="신청금액" required>
              <NumberInput value={form.requestAmount} onChange={(v) => setField('requestAmount', v)} />
            </Field>
            <Field label="신청일" required>
              <DateInput value={form.requestDate} onChange={(v) => setField('requestDate', v)} />
            </Field>
          </Form>
        </Drawer>
      ) : null}
    </div>
  );
}
